"""Frozen diagnostic-only ambiguity intervention, not a production change."""
from collections import defaultdict

def install(original):
    def reciprocal_ambiguities(self, pairs):
        by_track=defaultdict(list);by_row=defaultdict(list)
        for p in pairs:
            by_track[p[1]].append(p);by_row[p[2]].append(p)
        protected={}
        for tid,options in by_track.items():
            ordered=sorted(options,key=lambda p:(p[0],p[2]))
            best=ordered[0]
            if not self._established(best[3]) or not best[4].has_physical_proposal:
                continue
            if len(ordered)>1 and ordered[1][0]-best[0]<=self.policy.ambiguity_margin:
                continue
            predecessors=sorted(by_row[best[2]],key=lambda p:(p[0],p[1]))
            if predecessors[0][1]!=tid:
                continue
            if len(predecessors)>1 and predecessors[1][0]-predecessors[0][0]<=self.policy.ambiguity_margin:
                continue
            protected[tid]=best[2]
        # Only ambiguity attribution is narrowed. Original assignment, authority,
        # confirmation, scalar provenance and all numeric policies are unchanged.
        return original(self,[p for p in pairs if p[1] not in protected or protected[p[1]]==p[2]])
    return reciprocal_ambiguities
